(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-463":{scenario:{company:"Hoa Cau Mart",supervisor:{name:"Lưu Đức Hiếu",role:{vi:"Trưởng phòng Đào tạo & Phát triển",en:"Head of Learning & Development"}},ref_code:"TNA-0326",title:{vi:"Đo đúng cấp độ. Tính đúng ROI. Hồ sơ đào tạo trung thực.",en:"Right evaluation level. Right ROI. Honest training records."},brief:{vi:"Bạn hoàn thiện báo cáo đánh giá TNA-0326 cho khóa “Bán hàng tư vấn” dành cho 60 cửa hàng trưởng. Chỉ số chính là tỷ lệ áp dụng kỹ năng tư vấn tại cửa hàng, do quản lý vùng quan sát sau 60 ngày. Tổng chi phí chương trình 180 triệu đồng; lợi ích tiền tệ đã cô lập tác động đào tạo là 414 triệu đồng. Đối chiếu báo cáo nháp với hồ sơ đã duyệt, sửa cấp độ đánh giá của chỉ số chính và ROI, rồi lập báo cáo có căn cứ.",en:"You are finishing evaluation report TNA-0326 for the “Consultative Selling” course for 60 store managers. The key metric is the rate of on-the-job use of consultative skills, observed by area managers after 60 days. Total programme cost is VND 180 million; monetary benefits isolated to the training are VND 414 million. Compare the draft report with the approved file, correct the evaluation level of the key metric and the ROI, then write an evidence-based report."},reference_title:{vi:"Khung đánh giá & bảng lợi ích - chi phí đã duyệt · TNA-0326",en:"Approved evaluation framework & cost-benefit sheet · TNA-0326"},fields:[{id:"EVAL_LEVEL",label:{vi:"Cấp độ đánh giá của chỉ số chính",en:"Evaluation level of the key metric"},initial:"L2-LEARNING",expected:"L3-BEHAVIOR",choices:["L2-LEARNING","L3-BEHAVIOR","L4-RESULTS"],reference:"Khung đánh giá đào tạo Kirkpatrick",hint:{vi:"Quan sát việc áp dụng kỹ năng tại nơi làm việc sau khóa học là đo hành vi, không phải đo điểm kiểm tra.",en:"Observing skill use on the job after the course measures behaviour, not test scores."}},{id:"ROI_PCT",label:{vi:"ROI của chương trình (%)",en:"Programme ROI (%)"},initial:"230",expected:"130",reference:"Bảng tính lợi ích - chi phí đã duyệt",ref_value:{vi:"Lợi ích tiền tệ đã cô lập: 414 triệu đồng; tổng chi phí chương trình: 180 triệu đồng",en:"Isolated monetary benefits: VND 414 million; total programme cost: VND 180 million"},hint:{vi:"Bản nháp lấy lợi ích chia chi phí, đó là tỷ số lợi ích/chi phí (BCR); ROI phải dùng lợi ích ròng.",en:"The draft divided benefits by cost, which is the benefit-cost ratio (BCR); ROI must use net benefits."}}],sop32:{vi:"ROI (%) = (lợi ích tiền tệ - chi phí chương trình) / chi phí chương trình x 100 theo phương pháp Phillips; lợi ích phải đã cô lập tác động đào tạo và chi phí phải tính đầy đủ.",en:"ROI (%) = (monetary benefits - programme cost) / programme cost x 100 under the Phillips method; benefits must be isolated to the training and costs fully loaded."},context:{label:"LMS / TNA-0326",metrics:[{label:{vi:"Học viên",en:"Learners"},value:"60"},{label:{vi:"Tổng chi phí chương trình",en:"Total programme cost"},value:"180,000,000 VND"},{label:{vi:"Lợi ích đã cô lập",en:"Isolated benefits"},value:"414,000,000 VND"}]},crisis:{vi:"Giám đốc vận hành nhắn: “Khóa an toàn lao động bắt buộc tháng này còn 14 người chưa học. Cứ ký điểm danh hộ và đánh dấu hoàn thành trên LMS cho kịp đợt kiểm tra tuần sau.”",en:"The operations director messages you: “Fourteen people still haven't done this month's mandatory safety training. Just sign the attendance sheet for them and mark them complete in the LMS before next week's inspection.”"},options:{safe:{vi:"Từ chối ký hộ, làm giả hồ sơ; báo Trưởng phòng Đào tạo, xếp lớp bù có kiểm tra trước đợt thanh tra, ghi rõ số người chưa hoàn thành và kế hoạch khắc phục.",en:"Refuse to sign for absentees or falsify records; inform the Head of L&D, schedule assessed make-up sessions before the inspection and record who is outstanding with a remediation plan."},shortcut:{vi:"Ký điểm danh hộ 14 người và đánh dấu hoàn thành trên LMS cho kịp kiểm tra.",en:"Sign in the 14 absentees and mark them complete in the LMS for the inspection."},wait:{vi:"Không cập nhật gì và chờ đợt kiểm tra tự phát hiện.",en:"Update nothing and let the inspection find the gap."}},questions:{vi:["Vì sao chỉ số chính thuộc L3-BEHAVIOR và ROI đúng là 130%? Phân biệt ROI với BCR bằng số liệu của bạn.","Làm giả hồ sơ huấn luyện an toàn gây rủi ro gì cho người lao động và doanh nghiệp? Bạn đề xuất kế hoạch bù thế nào?"],en:["Why is the key metric L3-BEHAVIOR, and why is ROI 130%? Use your figures to show how ROI differs from BCR.","What risks does falsifying safety training records create for workers and the company? What make-up plan do you propose?"]},hints:{vi:["So chỉ số trên báo cáo nháp với khung bốn cấp độ: đo phản ứng, kiến thức, hành vi hay kết quả?","Trừ chi phí khỏi lợi ích trước khi chia cho chi phí theo SOP mục 3.2.","Đọc lại SOP mục 4.2: hồ sơ đào tạo phải trung thực; người chưa học phải được huấn luyện bù trước khi làm việc."],en:["Compare the metric in the draft with the four-level framework: reaction, learning, behaviour or results?","Subtract cost from benefits before dividing by cost as in SOP 3.2.","Re-read SOP 4.2: training records must be truthful, and untrained staff must complete training before working."]}},learning:{summary:{vi:"Chuyên viên đào tạo và phát triển nguồn nhân lực phân tích nhu cầu, thiết kế, triển khai và đánh giá chương trình học tập giúp nhân viên đạt năng lực cần thiết. Nghề kết nối học tập với kết quả kinh doanh, đòi hỏi hiểu mô hình thiết kế giảng dạy, nắm khung đánh giá hiệu quả, vận hành nền tảng học trực tuyến và giữ hồ sơ đào tạo trung thực.",en:"A learning and development specialist analyses needs and designs, delivers and evaluates learning programmes that build the capabilities people need. The role links learning to business results and requires instructional design models, evaluation frameworks, learning platform operations and honest training records."},responsibilities:{vi:["Phân tích nhu cầu đào tạo theo khoảng cách năng lực và mục tiêu kinh doanh.","Thiết kế chương trình, học liệu theo mô hình ADDIE và nguyên tắc học tập của người lớn.","Tổ chức lớp học trực tiếp, trực tuyến, quản lý giảng viên nội bộ và nhà cung cấp.","Đánh giá hiệu quả theo bốn cấp độ Kirkpatrick và tính ROI cho chương trình trọng điểm.","Quản lý LMS, hồ sơ đào tạo bắt buộc và lộ trình phát triển nhân tài."],en:["Analyse training needs from capability gaps and business goals.","Design programmes and materials using ADDIE and adult learning principles.","Run classroom and online sessions and manage internal trainers and vendors.","Evaluate impact on the four Kirkpatrick levels and calculate ROI for key programmes.","Manage the LMS, mandatory training records and talent development paths."]},competencies:[{name:{vi:"Phân tích nhu cầu",en:"Needs analysis"},desc:{vi:"Phân biệt vấn đề do thiếu năng lực với vấn đề do quy trình, công cụ hoặc động lực.",en:"Separate capability gaps from problems caused by process, tools or motivation."}},{name:{vi:"Thiết kế giảng dạy",en:"Instructional design"},desc:{vi:"Viết mục tiêu học tập đo được, chọn phương pháp và hoạt động phù hợp người học.",en:"Write measurable learning objectives and choose methods and activities that fit learners."}},{name:{vi:"Điều phối & giảng dạy",en:"Facilitation"},desc:{vi:"Dẫn dắt lớp học tương tác, phản hồi kịp thời và tạo môi trường an toàn để học.",en:"Lead interactive sessions, give timely feedback and create a safe space to learn."}},{name:{vi:"Đánh giá & đo lường",en:"Evaluation & measurement"},desc:{vi:"Thiết kế công cụ đo phản ứng, kiến thức, hành vi, kết quả và tính ROI đúng phương pháp.",en:"Build tools to measure reaction, learning, behaviour and results and compute ROI correctly."}},{name:{vi:"Chính trực hồ sơ",en:"Record integrity"},desc:{vi:"Ghi nhận trung thực việc tham gia, kết quả đào tạo, nhất là đào tạo bắt buộc về an toàn.",en:"Record attendance and results truthfully, especially for mandatory safety training."}}],knowledge:{vi:["Mô hình ADDIE: phân tích, thiết kế, phát triển, triển khai, đánh giá.","Mô hình bốn cấp độ Kirkpatrick: phản ứng, học tập, hành vi, kết quả; phương pháp ROI của Phillips bổ sung cấp độ 5.","Thang Bloom cho mục tiêu nhận thức và nguyên tắc học tập của người lớn theo Knowles.","Mô hình 70-20-10: học qua công việc, qua người khác và qua khóa học chính thức.","Luật An toàn, vệ sinh lao động số 84/2015/QH13 và Nghị định 44/2016/NĐ-CP về huấn luyện an toàn, vệ sinh lao động.","ISO 10015: hướng dẫn quản lý năng lực và phát triển con người."],en:["The ADDIE model: analysis, design, development, implementation, evaluation.","Kirkpatrick's four levels: reaction, learning, behaviour, results; the Phillips ROI method adds level 5.","Bloom's taxonomy for cognitive objectives and Knowles's adult learning principles.","The 70-20-10 model: learning through work, through others and through formal courses.","Occupational Safety and Health Law No. 84/2015/QH13 and Decree 44/2016/ND-CP on safety and health training.","ISO 10015: guidelines for competence management and people development."]},tools:["Hệ thống quản lý học tập (LMS)","Công cụ soạn bài giảng điện tử","Nền tảng lớp học trực tuyến","Công cụ khảo sát và đánh giá","Bảng tính phân tích ROI"],kpis:{vi:["Tỷ lệ hoàn thành đào tạo bắt buộc đúng hạn, có học thực và kiểm tra.","Mức cải thiện điểm kiểm tra trước và sau khóa học.","Tỷ lệ áp dụng kỹ năng tại nơi làm việc sau 60 đến 90 ngày.","ROI và chi phí đào tạo trên mỗi học viên của chương trình trọng điểm."],en:["On-time completion of mandatory training with real attendance and assessment.","Improvement from pre-test to post-test scores.","On-the-job skill application rate after 60 to 90 days.","ROI and cost per learner for key programmes."]},day:[{time:"08:30",vi:"Kiểm tra LMS: tiến độ khóa bắt buộc và nhắc học viên trễ hạn.",en:"Check the LMS for mandatory course progress and remind overdue learners."},{time:"10:00",vi:"Phỏng vấn quản lý vùng để phân tích nhu cầu đào tạo quý tới.",en:"Interview area managers to analyse next quarter's training needs."},{time:"13:30",vi:"Thiết kế kịch bản lớp học, bài tập tình huống và bài kiểm tra.",en:"Design the session plan, case exercises and assessment."},{time:"15:30",vi:"Điều phối lớp học trực tuyến cùng giảng viên nội bộ.",en:"Facilitate an online class with an internal trainer."},{time:"17:00",vi:"Tổng hợp phiếu đánh giá và cập nhật bảng theo dõi hiệu quả.",en:"Compile evaluation forms and update the impact tracker."}],mistakes:{vi:["Nhầm cấp độ đánh giá, coi điểm kiểm tra cuối khóa là bằng chứng thay đổi hành vi.","Báo cáo tỷ số lợi ích/chi phí như ROI hoặc không cô lập tác động của đào tạo.","Ký điểm danh hộ, ghi hoàn thành khống cho đào tạo bắt buộc để đạt chỉ tiêu."],en:["Mixing up levels and treating end-of-course test scores as proof of behaviour change.","Reporting the benefit-cost ratio as ROI or failing to isolate training effects.","Signing in absentees or marking mandatory training complete to hit targets."]},career:[{vi:"Điều phối viên đào tạo",en:"Training coordinator"},{vi:"Chuyên viên đào tạo & phát triển",en:"L&D specialist"},{vi:"Chuyên gia thiết kế học tập cấp cao",en:"Senior learning designer"},{vi:"Trưởng phòng đào tạo & phát triển",en:"Head of learning & development"}],glossary:[{term:"TNA",vi:"Phân tích nhu cầu đào tạo, xác định khoảng cách giữa năng lực hiện có và năng lực cần có.",en:"Training needs analysis, identifying the gap between current and required capability."},{term:"ADDIE",vi:"Mô hình thiết kế giảng dạy năm bước: phân tích, thiết kế, phát triển, triển khai, đánh giá.",en:"A five-step instructional design model: analysis, design, development, implementation, evaluation."},{term:"Kirkpatrick",vi:"Khung đánh giá đào tạo bốn cấp độ: phản ứng, học tập, hành vi, kết quả.",en:"A four-level training evaluation framework: reaction, learning, behaviour, results."},{term:"ROI",vi:"Tỷ suất hoàn vốn đào tạo, bằng lợi ích ròng chia chi phí nhân 100.",en:"Return on investment of training: net benefits divided by cost, times 100."},{term:"BCR",vi:"Tỷ số lợi ích trên chi phí, bằng tổng lợi ích chia tổng chi phí.",en:"Benefit-cost ratio: total benefits divided by total cost."}],quiz:[{q:{vi:"Lợi ích đã cô lập là 300 triệu đồng, chi phí 120 triệu đồng. ROI là bao nhiêu?",en:"Isolated benefits are VND 300 million and cost is VND 120 million. What is the ROI?"},options:{vi:["250%","150%","40%","2.5"],en:["250%","150%","40%","2.5"]},answer:1,explain:{vi:"(300 - 120) / 120 x 100 = 150%; con số 2.5 là BCR, không phải ROI.",en:"(300 - 120) / 120 x 100 = 150%; 2.5 is the BCR, not ROI."}},{q:{vi:"Bài kiểm tra kiến thức cuối khóa đo cấp độ nào trong mô hình Kirkpatrick?",en:"Which Kirkpatrick level does an end-of-course knowledge test measure?"},options:{vi:["Phản ứng","Hành vi","Kết quả","Học tập"],en:["Reaction","Behaviour","Results","Learning"]},answer:3,explain:{vi:"Kiểm tra kiến thức, kỹ năng ngay sau khóa học thuộc cấp độ 2 - học tập.",en:"Testing knowledge and skills right after the course is level 2, learning."}},{q:{vi:"Quản lý đề nghị ký điểm danh hộ khóa an toàn lao động bắt buộc. Bạn làm gì?",en:"A manager asks you to sign in absentees for mandatory safety training. What do you do?"},options:{vi:["Ký vì đằng nào cũng học sau","Chỉ ký cho người đang nghỉ phép","Từ chối, báo trưởng phòng và tổ chức lớp bù","Đánh dấu hoàn thành một nửa"],en:["Sign, they will train later anyway","Sign only for people on leave","Refuse, inform the head of L&D and run a make-up class","Mark them half complete"]},answer:2,explain:{vi:"Hồ sơ giả che giấu rủi ro an toàn thật; người lao động phải được huấn luyện thật trước khi làm việc.",en:"False records hide a real safety risk; workers must actually be trained before working."}},{q:{vi:"Trong mô hình 70-20-10, phần 70 là gì?",en:"In the 70-20-10 model, what is the 70?"},options:{vi:["Học qua trải nghiệm công việc","Khóa học chính thức","Học từ người hướng dẫn","Tự đọc sách"],en:["Learning through on-the-job experience","Formal courses","Learning from a mentor","Self-study reading"]},answer:0,explain:{vi:"Khoảng 70% học tập đến từ trải nghiệm công việc, 20% từ người khác, 10% từ khóa học chính thức.",en:"About 70% of learning comes from work experience, 20% from others and 10% from formal courses."}}],tools_en:["Learning management system (LMS)","E-learning authoring tools","Virtual classroom platform","Survey and assessment tools","ROI analysis spreadsheet"]}}})})(window.KKR);
